def transform(wb):
    ws = wb["merge"]
    totals = {}
    for r in range(2, 1001):
        a = ws.cell(row=r, column=1).value
        b = ws.cell(row=r, column=2).value
        c = ws.cell(row=r, column=3).value
        if a is None and b is None and c is None:
            continue
        d = ws.cell(row=r, column=4).value
        if d is None:
            d = 0
        key = (a, b, c)
        if key in totals:
            totals[key] = totals[key] + d
        else:
            totals[key] = d
    row = 2
    for key in totals:
        if row <= 1000:
            ws.cell(row=row, column=7).value = key[0]
            ws.cell(row=row, column=8).value = key[1]
            ws.cell(row=row, column=9).value = key[2]
            ws.cell(row=row, column=10).value = totals[key]
            row = row + 1
    for r in range(row, 1001):
        ws.cell(row=r, column=7).value = None
        ws.cell(row=r, column=8).value = None
        ws.cell(row=r, column=9).value = None
        ws.cell(row=r, column=10).value = None
